-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (9260, 20, 'Offene Jugendarbeit und Jugendfreizeiteinrichtungen ausbauen und verlässlich finanzieren (Land)', 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'belegt', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'land', null, true, 'blind', null),
  (9261, 20, 'Verbindliche Mindestversorgung mit Jugendorten per Gesetz, Pflichtaufgabe oder Zielwert (Land)', 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'belegt', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'land', null, true, 'blind', null),
  (9262, 20, 'Jugendbudgets in Kommunen und Bezirken (Land)', 'Jugendbudgets lassen Jugendliche selbst über Angebote entscheiden und sind leicht einzuführen; die Summen sind meist klein und Wirkungen auf das Angebot kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (9263, 20, 'Treffpunkte für Jugendliche im öffentlichen Raum und in der Quartiersplanung vorsehen (Land)', 'Schafft unmittelbar Aufenthaltsorte, die Jugendliche laut Befragungen vermissen; Wirkung und Konfliktfreiheit solcher Orte sind wenig untersucht, die Umsetzung liegt bei den Kommunen.', 'offen', null, 'land', null, true, 'blind', null),
  (9264, 20, 'Leerstand und Zwischennutzungen für Jugendorte öffnen (Land)', 'Nutzt vorhandene Flächen für Jugendorte, auch in dichten Quartieren, und ist vergleichsweise günstig; Zwischennutzungen sind oft befristet, Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (9265, 20, 'Vergünstigte Karten für Kulturangebote für Jugendliche (Land)', 'Senkt Kosten für einzelne Kulturbesuche und ist einfach umsetzbar; schafft aber keine Treffpunkte, und ob Ermäßigungen die Teilnahme Jugendlicher erhöhen, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (9266, 20, 'Schutzkonzepte und Sicherheit in Jugendfreizeiteinrichtungen (Land)', 'Sichere Einrichtungen können verhindern, dass Jugendliche Treffs meiden; mehr Orte oder Angebote entstehen dadurch nicht, und die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (9267, 20, 'Förderung von Kinder- und Jugendverbänden und Jugendringen (Land)', 'Jugendverbände tragen Gruppen- und Ferienangebote, Förderung ist leicht umsetzbar; ohne Bezug zu Orten oder konkretem Ausbau bleibt der Effekt auf das Angebot unbestimmt.', 'offen', null, 'land', null, true, 'blind', null),
  (9268, 20, 'Bundesförderung von Jugendverbänden und jugendlichem Engagement, u. a. Kinder- und Jugendplan (Bund)', 'Der Bund fördert Jugendverbände bereits über den Kinder- und Jugendplan; diese Mittel stärken vor allem überregionale Strukturen und erreichen Treffs vor Ort nur am Rand.', 'offen', null, 'bund', null, true, 'blind', null),
  (9269, 20, 'Bundesprogramm für kommunale Jugendfreizeit-Infrastruktur und Jugendarbeit (Bund)', 'Bundesgeld kann Kommunen Aufbau und Erhalt von Jugendeinrichtungen ermöglichen, deren Nutzen belegt ist; der Bund darf nur befristet mitfinanzieren, Betrieb bleibt Sache von Ländern und Kommunen.', 'belegt', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'bund', null, true, 'blind', null),
  (9270, 20, 'Parkbetreuung zur Konfliktvermittlung in Grünanlagen (Land)', 'Präsenz von Vermittelnden kann Nutzungskonflikte entschärfen und ist günstig; das Angebot ist nicht auf Jugendliche zugeschnitten, unabhängige Evaluationen fehlen.', 'offen', null, 'land', null, true, 'blind', null),
  (9271, 20, 'E-Sport und Gaming fördern (Land)', 'Spricht ein verbreitetes Freizeitinteresse Jugendlicher an; schafft aber kaum Orte, Gemeinnützigkeit von E-Sport regelt der Bund, Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null)
