insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (9272, 20, 11, 'BE', 'Verbindliche Schutzkonzepte für alle Jugendclubs mit Schulungen des Personals und Umsetzung im Alltag', '{2001}', 9266, 1, 3, null, 'Sichere Einrichtungen können verhindern, dass Jugendliche Treffs meiden; mehr Orte oder Angebote entstehen dadurch nicht, und die Wirkung ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=13', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9273, 20, 11, 'BE', 'Jugendclubs als Orte der Begegnung und Demokratiebildung fördern', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=64', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9274, 20, 11, 'BE', 'Jugendfreizeiteinrichtungen weiter ausbauen und modernisieren', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=109', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9275, 20, 11, 'BE', 'Diverse Orte für Kinder und Jugendliche zugänglicher machen: Calisthenikanlagen in Parks ausbauen, ungenutzte öffentliche Räume zum ungestörten Aufenthalt umgestalten', '{2003,2001}', 9263, 2, 2, null, 'Schafft unmittelbar Aufenthaltsorte, die Jugendliche laut Befragungen vermissen; Wirkung und Konfliktfreiheit solcher Orte sind wenig untersucht, die Umsetzung liegt bei den Kommunen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=109', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9276, 20, 11, 'BE', 'Sportangebote für Kinder und Jugendliche in allen Bezirken ausbauen („Sport 365“)', '{2001}', null, 2, 3, null, 'Ganzjährige, wohnortnahe Sportangebote in allen Bezirken erweitern das Freizeitangebot direkt und bauen auf einem laufenden Programm auf; die Wirkung des Programms ist nicht unabhängig untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=113', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9277, 20, 11, 'BE', 'Vergünstigte Kulturtickets auf Kinder und Jugendliche ausweiten', '{2001}', 9265, 1, 3, null, 'Senkt Kosten für einzelne Kulturbesuche und ist einfach umsetzbar; schafft aber keine Treffpunkte, und ob Ermäßigungen die Teilnahme Jugendlicher erhöhen, ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=120', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9278, 20, 11, 'BE', 'Digitaler Chancenpass als App mit Überblick über Angebote im Kiez und Zugang zu Bildungs- und Freizeitangeboten für Kinder und Familien', '{2001}', null, 2, 2, null, 'Eine App mit Überblick und direktem Zugang kann die geringe Nutzung von Teilhabeleistungen erhöhen; schafft aber keine Angebote, Aufbau und Datenschutz brauchen Zeit.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=103', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9279, 20, 11, 'MV', 'Modellprojekt für mobile Kinder- und Jugendzentren im ländlichen Raum, um die Erreichbarkeit der Angebote zu verbessern', '{2001}', null, 1, 3, null, 'Mobile Jugendzentren verbessern die Erreichbarkeit im ländlichen Raum; als einzelnes Modellprojekt bleibt die Reichweite klein, die Wirkung mobiler Angebote ist wenig untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9280, 20, 11, 'MV', 'Landesprogramm zur Stärkung der Jugend- und Straßensozialarbeit, um auf neue Problemlagen niedrigschwellig zu reagieren', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9281, 20, 11, 'MV', 'Förderung lokaler Kulturorte und Einrichtungen, darunter Jugendclubs und mobile Clubs', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=129', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9282, 20, 11, 'MV', 'Rechtliche Hürden abbauen, damit Senioren- und Jugendarbeit gemeinsam gefördert werden können', '{2001}', null, 1, 3, null, 'Gemeinsame Förderung kann generationsübergreifende Orte gerade in kleinen Gemeinden tragfähig machen; zusätzliche Mittel gibt es nicht, die Wirkung ist offen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=98', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9283, 20, 11, 'ST', 'Offene Jugendarbeit und Jugendverbände dauerhaft und verlässlich unterstützen.', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=32', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9284, 20, 12, null, 'Förderung von Popkultur ausbauen, um vielfältige kulturelle Angebote für jüngere Zielgruppen zu schaffen.', '{2001}', null, 1, 3, null, 'Popkulturförderung kann Angebote für junge Menschen erweitern; sie zielt auf Kulturbetrieb, nicht auf Treffpunkte, die Wirkung für Jugendliche ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=51', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9285, 20, 12, null, 'Jugendverbände, Jugendparlamente und ähnliche Strukturen weiter unterstützen.', '{2001}', 9268, 1, 3, null, 'Der Bund fördert Jugendverbände bereits über den Kinder- und Jugendplan; diese Mittel stärken vor allem überregionale Strukturen und erreichen Treffs vor Ort nur am Rand.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9286, 20, 12, 'BE', 'Treffpunkte für Jugendliche im öffentlichen Raum schaffen, Finanzierung in den Bezirken gesetzlich absichern; Nutzung ohne Geld zahlen', '{2001}', 9261, 3, 2, null, 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9287, 20, 12, 'BE', 'Leerstehende Ladenflächen und Einkaufszentren für Jugendangebote beleben und Zwischennutzungen erleichtern', '{2001}', 9264, 2, 2, null, 'Nutzt vorhandene Flächen für Jugendorte, auch in dichten Quartieren, und ist vergleichsweise günstig; Zwischennutzungen sind oft befristet, Wirkung kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=19', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9288, 20, 12, 'BE', 'Arbeit der Kinder- und Jugendverbände stärken (Grenzfall: Verbandsförderung, kein Angebot oder Ort selbst)', '{2001}', 9267, 1, 3, null, 'Jugendverbände tragen Gruppen- und Ferienangebote, Förderung ist leicht umsetzbar; ohne Bezug zu Orten oder konkretem Ausbau bleibt der Effekt auf das Angebot unbestimmt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=39', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9289, 20, 12, 'BE', 'Lärmschutz-Vorgaben anpassen, damit junge Menschen nicht aus dem öffentlichen Raum verdrängt werden', '{2003}', null, 2, 2, null, 'Großzügigere Lärmregeln für Jugendtreffpunkte setzen direkt an Beschwerden an, die zur Schließung führen; Rahmen ist Bundesrecht, Länder können nur Richtlinien anpassen, Wirkung ist wenig untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9290, 20, 12, 'MV', 'Jugendclubs, soziokulturelle Zentren und offene Treffpunkte für Jugendliche stärken und neu schaffen', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=36', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9291, 20, 12, 'ST', 'Jugendclubs, pädagogisch begleitete Freiräume und selbstorganisierte Räume für Jugendliche weiter stärken', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=26', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9292, 20, 12, 'ST', 'Kommunen gezielt unterstützen, Jugendbudgets bereitzustellen und Angebote für Jugendliche zu ermöglichen', '{2001}', 9262, 1, 3, null, 'Jugendbudgets lassen Jugendliche selbst über Angebote entscheiden und sind leicht einzuführen; die Summen sind meist klein und Wirkungen auf das Angebot kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=25', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9293, 20, 12, 'ST', 'Verbindlichen Jugendförderplan mit Mindeststandards für Angebote des Landes erarbeiten', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=25', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9294, 20, 12, 'ST', 'Digitale Jugendarbeit ausbauen', '{2001}', null, 1, 3, null, 'Digitale Angebote erreichen auch Jugendliche fern von Treffs; sie ersetzen keine physischen Orte, die Wirkung ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=26', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9295, 20, 12, 'ST', 'Kreis-Kinder- und Jugendringe finanziell und personell besser ausstatten', '{2001}', 9267, 1, 3, null, 'Jugendverbände tragen Gruppen- und Ferienangebote, Förderung ist leicht umsetzbar; ohne Bezug zu Orten oder konkretem Ausbau bleibt der Effekt auf das Angebot unbestimmt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=26', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9296, 20, 12, 'ST', 'Leitlinie für die Förderung von E-Sport erarbeiten, E-Sport den traditionellen Sportarten gleichstellen', '{2001}', 9271, 1, 2, null, 'Spricht ein verbreitetes Freizeitinteresse Jugendlicher an; schafft aber kaum Orte, Gemeinnützigkeit von E-Sport regelt der Bund, Wirkung ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=41', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9297, 20, 13, null, 'Sonderprogramm über zehn Jahre, mit dem Kommunen Strukturen der Kinder- und Jugendarbeit aufbauen und stärken', '{2001}', 9269, 2, 2, null, 'Bundesgeld kann Kommunen Aufbau und Erhalt von Jugendeinrichtungen ermöglichen, deren Nutzen belegt ist; der Bund darf nur befristet mitfinanzieren, Betrieb bleibt Sache von Ländern und Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9298, 20, 13, null, 'Mittel des Kinder- und Jugendplans (zentrales Förderinstrument für Jugendarbeit) aufstocken und an Bedarfe anpassen', '{2001}', 9268, 1, 3, null, 'Der Bund fördert Jugendverbände bereits über den Kinder- und Jugendplan; diese Mittel stärken vor allem überregionale Strukturen und erreichen Treffs vor Ort nur am Rand.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9299, 20, 13, null, 'Feministische Mädchen- und Jungenarbeit sowie queersensible Angebote besonders fördern', '{2001}', null, 1, 3, null, 'Zielgruppenspezifische Angebote können Jugendliche erreichen, die allgemeine Treffs meiden; der Bund fördert nur Modelle, die Breitenwirkung ist begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9300, 20, 13, null, 'Sichere und selbst gestaltete Aufenthaltsorte für Jugendliche im öffentlichen Raum schaffen', '{2001}', null, 2, 2, null, 'Selbst gestaltete Aufenthaltsorte entsprechen dem Wunsch Jugendlicher nach Treffpunkten; der Bund kann nur über Förderprogramme beitragen, Umfang und Wirkung sind offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9301, 20, 13, null, 'Freiräume und Ressourcen für jugendliches Engagement, unter anderem über Förderprogramme', '{2001}', 9268, 1, 3, null, 'Der Bund fördert Jugendverbände bereits über den Kinder- und Jugendplan; diese Mittel stärken vor allem überregionale Strukturen und erreichen Treffs vor Ort nur am Rand.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9302, 20, 13, null, 'Jugendverbände mit Schwerpunkt Integration und Demokratie gezielt unterstützen', '{2001}', 9268, 1, 3, null, 'Der Bund fördert Jugendverbände bereits über den Kinder- und Jugendplan; diese Mittel stärken vor allem überregionale Strukturen und erreichen Treffs vor Ort nur am Rand.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9303, 20, 13, null, 'Auskömmlichere Kommunalfinanzierung und Deutschlandfonds, damit Kommunen Investitionen etwa in Jugendclubs finanzieren können', '{2001}', null, 1, 2, null, 'Bessere Kommunalfinanzen ermöglichen auch Investitionen in Jugendclubs; das Geld ist nicht zweckgebunden, ob es bei Jugendorten ankommt, bleibt offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9304, 20, 13, null, 'Leistungen für Bildung und Teilhabe direkter abrufbar machen, auch für Sportvereine und Musikschulen', '{2002}', null, 2, 3, null, 'Nur ein kleiner Teil berechtigter Kinder nutzt die Teilhabeleistung, auch wegen Bürokratie; direkte Abrechnung über Vereine kann das ändern. Der Betrag bleibt niedrig, fehlende Angebote vor Ort löst sie nicht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=83', 'https://www.der-paritaetische.de/alle-meldungen/paritaetische-expertise-zeigt-nicht-einmal-jedes-fuenfte-kind-im-buergergeldbezug-profitiert-von-teilhabeleistungen/', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9305, 20, 13, null, 'Kulturpass für Jugendliche verstetigen (Guthaben, um Kultur zu entdecken)', '{2002}', null, 1, 3, null, 'Ein Kulturguthaben senkt einmalig Kosten für Kultur; es erreicht nur einen Jahrgang, ein Großteil wird für Bücher und Kino genutzt, die Evaluation steht aus.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=125', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9306, 20, 13, 'BE', 'Offene Jugendarbeit und Jugendfreizeiteinrichtungen langfristig finanziell ausstatten', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=157', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9307, 20, 13, 'BE', 'Bei der Quartiersplanung eigene Treffpunkte und Freiräume für Kinder und Jugendliche vorsehen', '{2001}', 9263, 2, 2, null, 'Schafft unmittelbar Aufenthaltsorte, die Jugendliche laut Befragungen vermissen; Wirkung und Konfliktfreiheit solcher Orte sind wenig untersucht, die Umsetzung liegt bei den Kommunen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9308, 20, 13, 'BE', 'Parkläufer- und Kiezmanager-Programm fortführen und dauerhaft sichern', '{2003}', 9270, 1, 3, null, 'Präsenz von Vermittelnden kann Nutzungskonflikte entschärfen und ist günstig; das Angebot ist nicht auf Jugendliche zugeschnitten, unabhängige Evaluationen fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9309, 20, 13, 'BE', 'In jedem Bezirk mindestens einen queeren Ort schaffen, auch als Jugendclub', '{2001}', null, 1, 2, null, 'Ein queerer Ort je Bezirk schafft sichere Treffpunkte für eine Teilgruppe; nur teils als Jugendclub, Breitenwirkung für alle Jugendlichen begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=150', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9310, 20, 13, 'BE', 'Verkehrsberuhigte Quartiere gestalten, mit Raum zum Spielen und für Treffpunkte von Jugendlichen', '{2001}', null, 1, 2, null, 'Verkehrsberuhigte Quartiere schaffen nebenbei Aufenthaltsflächen auch für Jugendliche; der Schwerpunkt liegt auf Verkehr, eigene Jugendorte sind nicht zugesagt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=89', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9311, 20, 13, 'BE', 'E-Sport und Gaming-Strukturen gemeinnützig fördern', '{2001}', 9271, 1, 2, null, 'Spricht ein verbreitetes Freizeitinteresse Jugendlicher an; schafft aber kaum Orte, Gemeinnützigkeit von E-Sport regelt der Bund, Wirkung ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=38', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9312, 20, 13, 'BE', 'Kinder- und Jugendfreizeiteinrichtungen im Umgang mit rechtsextremen Einstellungen stärken', '{2001}', 9266, 1, 3, null, 'Sichere Einrichtungen können verhindern, dass Jugendliche Treffs meiden; mehr Orte oder Angebote entstehen dadurch nicht, und die Wirkung ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=160', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9313, 20, 13, 'MV', 'Offene Kinder- und Jugendarbeit fördern und sichere Treffpunkte schaffen', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9314, 20, 13, 'MV', 'Nachbarschaftstreffs als Orte der Gemeinschaft in jeder Kommune; Veranstaltungen für unter 25 kostenlos', '{2001}', null, 1, 2, null, 'Ein Treffpunkt je Stadtteil mit kostenlosen Veranstaltungen für unter 25 schafft Orte, die auch Jugendliche nutzen können; sie sind nicht jugendspezifisch, die Finanzierung ist offen.', 'https://gruene-mv.de/?wpdmdl=33772#page=63', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9315, 20, 13, 'MV', 'Kostenfreies Deutschlandticket für alle unter 27, damit sie auch Jugendclubs und Freizeiteinrichtungen erreichen', '{2001}', null, 1, 1, null, 'Kostenlose Mobilität erleichtert den Weg zu Jugendclubs; schafft aber keine Orte, und ein landesweit kostenfreies Ticket für alle unter 27 ist sehr teuer und nur mit Bund und Verbünden möglich.', 'https://gruene-mv.de/?wpdmdl=33772#page=23', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9316, 20, 13, 'ST', 'Jugendorte schaffen und ausbauen, auch unbeplante Räume und selbstverwaltete Jugendzentren', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9317, 20, 13, 'ST', 'Offene Jugendarbeit, insbesondere mobile Jugendarbeit, massiv stärken', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9318, 20, 14, null, 'Engagement der Babyboomer-Generation gezielt einbinden, um Sportangebote für Kinder und Jugendliche auszubauen', '{2001}', null, 1, 2, null, 'Mehr Ehrenamtliche können Sportangebote für Jugendliche erweitern; der Bund kann Engagement nur anregen, ein konkretes Instrument fehlt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9319, 20, 14, 'BE', 'Finanzierung eines Projekts verstetigen, das Konflikte zwischen Nutzenden und Anwohnenden von Grünanlagen niedrigschwellig deeskaliert', '{2003}', 9270, 1, 3, null, 'Präsenz von Vermittelnden kann Nutzungskonflikte entschärfen und ist günstig; das Angebot ist nicht auf Jugendliche zugeschnitten, unabhängige Evaluationen fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=70', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9320, 20, 14, 'BE', 'Kultureinrichtungen finanziell ermöglichen, vergünstigte Karten für Jugendliche anzubieten', '{2001}', 9265, 1, 3, null, 'Senkt Kosten für einzelne Kulturbesuche und ist einfach umsetzbar; schafft aber keine Treffpunkte, und ob Ermäßigungen die Teilnahme Jugendlicher erhöhen, ist kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=104', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9321, 20, 14, 'ST', 'Mittel der Jugendhilfe des Landes an den Verbraucherpreisindex anpassen und erhöhen', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=35', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9322, 20, 15, 'BE', 'Jugendhäuser sollen wieder sichere Orte für Kinder und Jugendliche sein.', '{2001}', 9266, 1, 3, null, 'Sichere Einrichtungen können verhindern, dass Jugendliche Treffs meiden; mehr Orte oder Angebote entstehen dadurch nicht, und die Wirkung ist kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9323, 20, 15, 'ST', 'Förderung der SIMSON-Kultur als Teil der Jugendkultur', '{2001}', null, 1, 2, null, 'Fördert ein bestimmtes Hobby einer Teilgruppe Jugendlicher; wie gefördert werden soll, bleibt offen, Orte oder breite Angebote entstehen kaum.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=203', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9324, 20, 16, null, 'Freizeiteinrichtungen und Treffpunkte für Kinder und Jugendliche niedrigschwellig, wohnortnah und gebührenfrei machen; Finanzierung der Kommunen verbessern, Länder kofinanzieren.', '{2001,2002}', null, 2, 1, null, 'Gebührenfreie, wohnortnahe Einrichtungen senken Kostenhürden und sichern Orte; der Bund kann Gebührenfreiheit kommunaler und Vereinsangebote nicht anordnen, die Finanzierung ist ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9325, 20, 16, null, 'Queere Jugendarbeit wird kommunale Pflichtaufgabe; queere Orte wie Jugendzentren sollen vor Mieterhöhungen und Kürzungen geschützt werden.', '{2001}', null, 1, 1, null, 'Sichert Orte für eine kleine Zielgruppe; der Bund darf Kommunen nach dem Grundgesetz keine neuen Aufgaben übertragen, Schutz vor Mieterhöhungen ist rechtlich schwer.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9326, 20, 16, 'BE', 'Jugendclubs, Abenteuerspielplätze, Sporthallen, Stadtbibliotheken und selbstverwaltete Treffpunkte sichern und ausbauen', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=177', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9327, 20, 16, 'BE', 'Mindestens einen selbstverwalteten Jugendort pro Bezirk unterstützen', '{2001}', 9261, 3, 2, null, 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=177', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9328, 20, 16, 'BE', 'Abendliche und wetterunabhängige Raumnutzung verbessern, Kooperation der Jugendarbeit mit Stadtteilzentren und Sportvereinen stärken', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=177', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9329, 20, 16, 'BE', 'Jugendbeteiligung mit verbindlichen Jugendbudgets in allen Bezirken verankern', '{2001}', 9262, 1, 3, null, 'Jugendbudgets lassen Jugendliche selbst über Angebote entscheiden und sind leicht einzuführen; die Summen sind meist klein und Wirkungen auf das Angebot kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=176', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9330, 20, 16, 'BE', 'Zweckbindung der Mittel der Kinder- und Jugendhilfe, Geld für Jugendclubs soll bei den Jugendclubs ankommen', '{2001}', null, 2, 3, null, 'Zweckbindung verhindert, dass Mittel für Jugendclubs anderweitig ausgegeben werden, und sichert so bestehende Orte; zusätzliche Mittel bringt sie nicht, Kommunen verlieren Spielraum.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=181', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9331, 20, 16, 'MV', 'Kinder- und Jugendarbeit zur kommunalen Pflichtaufgabe machen und den Landesjugendplan bedarfsgerecht ausfinanzieren', '{2001}', 9261, 3, 2, null, 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9332, 20, 16, 'ST', 'Landesweiter Rechtsanspruch auf Kinder- und Jugendarbeit mit Mindeststandard; Förderung kommunaler Maßnahmen dynamisch erhöhen', '{2001}', 9261, 3, 2, null, 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=61', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9333, 20, 16, 'ST', 'Freiräume aus Leerstand gemeinsam mit Jugendlichen gestalten und nutzen', '{2001}', 9264, 2, 2, null, 'Nutzt vorhandene Flächen für Jugendorte, auch in dichten Quartieren, und ist vergleichsweise günstig; Zwischennutzungen sind oft befristet, Wirkung kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9334, 20, 16, 'ST', 'Verlässliche Öffnungszeiten, stabile Teams und sichere Räume für Jugendangebote, ohne Antragsaufwand', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=63', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9335, 20, 16, 'ST', 'Jugendorte in jedem Ortsteil in etwa 15 Minuten erreichbar machen, wo es fehlt mit mobilem Angebot vor Ort', '{2001}', 9261, 3, 2, null, 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=64', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9336, 20, 16, 'ST', 'Investitionspfad: fehlende Jugendorte benennen, finanzieren und terminieren', '{2001}', 9261, 3, 2, null, 'Rechtsanspruch, Pflichtaufgabe oder Erreichbarkeitsziel sichern Jugendorte flächendeckend und gegen Kürzungen; Wirkung von Jugendclubs ist belegt. Dagegen: hohe Dauerkosten für Land und Kommunen, Aufbau dauert mehrere Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=65', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9337, 20, 16, 'ST', 'Ferien- und Schullandheim-Angebote als feste Säule sichern, Teilnahme unabhängig vom Geldbeutel', '{2001}', null, 1, 2, null, 'Ferienangebote unabhängig vom Einkommen erweitern Freizeit für ärmere Jugendliche; es geht um einzelne Fahrten, nicht um verlässliche Orte, die Finanzierung ist offen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9338, 20, 16, 'ST', 'Zugang zu offenen Angeboten ohne Nachweispflichten und ohne formale Kriterien', '{2001}', null, 1, 3, null, 'Zugang ohne Nachweise senkt Hürden für offene Angebote und kostet wenig; mehr Orte oder Angebote entstehen dadurch nicht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9339, 20, 17, null, 'Investitionsprogramm für kinder- und jugendfreundliche Infrastruktur; wohnortnaher, niedrigschwelliger Zugang zu Jugendfreizeiteinrichtungen', '{2001}', 9269, 2, 2, null, 'Bundesgeld kann Kommunen Aufbau und Erhalt von Jugendeinrichtungen ermöglichen, deren Nutzen belegt ist; der Bund darf nur befristet mitfinanzieren, Betrieb bleibt Sache von Ländern und Kommunen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9340, 20, 17, null, 'Der Bund übernimmt für alle Kinder das erste Vereinsjahr im Sport per Zuschuss', '{2002}', null, 1, 2, null, 'Ein Zuschuss für das erste Vereinsjahr senkt Kosten beim Einstieg; er ist einmalig, schafft kein Angebot, und Zuschüsse wie die Teilhabeleistung erreichen ärmere Kinder bisher schlecht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9341, 20, 17, 'BE', 'Angebote der Jugendarbeit ausbauen, neben Sprach- und Integrationsangeboten im Rahmen von Präventionsprojekten', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9342, 20, 17, 'BE', 'Kostenlose oder stark vergünstigte Nutzung kommunaler Sportanlagen für Vereine, freier Zugang für Kinder und Jugendliche', '{2001}', null, 1, 2, null, 'Freier Zugang zu Sportanlagen öffnet Orte für Jugendliche ohne Kosten; Kommunen verlieren Einnahmen, und offene Nutzungszeiten neben dem Vereinsbetrieb sind begrenzt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9343, 20, 17, 'MV', 'Ausbau kostenfreier und niedrigschwelliger Freizeitangebote für Kinder und Jugendliche', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=13', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9344, 20, 17, 'MV', 'Stärkung selbstorganisierter, ehrenamtlich gestalteter Jugendarbeit', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=13', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9345, 20, 17, 'MV', 'Langfristige Absicherung und verlässliche Finanzierung von Jugendclubs, Freizeithäusern und offenen Treffpunkten', '{2001}', 9260, 2, 2, null, 'Mehr und verlässlich geöffnete Jugendtreffs setzen direkt am Mangel an Orten an; Schließungen senkten in London nachweislich Teilnahme und erhöhten Jugenddelinquenz. Ohne Zielwert und Finanzierungszusage bleibt der Umfang offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=13', 'https://www.economicsobservatory.com/what-are-the-effects-of-youth-club-closures-in-the-uk', 'belegt', '2026-10-11', false, true, 'blind', null),
  (9346, 20, 17, 'MV', 'Verlässliche Förderung von Vereinen und Initiativen, die Kinder und Jugendliche aus einkommensschwachen Familien erreichen', '{2001}', null, 1, 3, null, 'Verlässliche Förderung kann Angebote für ärmere Kinder sichern; unklar bleibt, ob es um Freizeitangebote oder allgemeine Unterstützung geht, der Umfang ist offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=13', null, 'offen', '2026-10-11', false, true, 'blind', null),
  (9347, 20, 17, 'ST', 'Förderprogramme für junge Menschen gezielt ausbauen, um Teilhabe sowie kulturelle und kreative Fähigkeiten zu fördern', '{2001}', null, 1, 3, null, 'Mehr Förderprogramme können kulturelle Freizeitangebote erweitern; Umfang und Zielrichtung sind unbestimmt, Orte entstehen nicht zwingend.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=73', null, 'offen', '2026-10-11', false, true, 'blind', null);

